 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = Counter(v for row in grid for v in row)
    candidates = []
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            candidates.append((freq[next(iter(vals))], 'v', c))
    for r in range(h):
        if len(set(grid[r])) == 1:
            candidates.append((freq[grid[r][0]], 'h', r))
    _, axis, pos = min(candidates)
    if axis == 'v':
        a = [row[:pos] for row in grid]
        b = [row[pos+1:] for row in grid]
    else:
        a, b = grid[:pos], grid[pos+1:]
    nr, nc = min(len(a), len(b)), min(len(a[0]), len(b[0]))
    a = [row[:nc] for row in a[:nr]]
    b = [row[:nc] for row in b[:nr]]
    equal = [a[r][c] for r in range(nr) for c in range(nc) if a[r][c] == b[r][c]]
    fill = Counter(equal).most_common(1)[0][0]
    return [[3 if a[r][c] == b[r][c] else fill for c in range(nc)] for r in range(nr)]
