 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the solid separator line between the two panels.
    cuts = []
    for c in range(w):
        if all(row[c] == grid[0][c] for row in grid):
            cuts.append(('v', c))
    for r in range(h):
        if all(v == grid[r][0] for v in grid[r]):
            cuts.append(('h', r))
    axis, p = min(cuts, key=lambda x: abs((w if x[0] == 'v' else h) / 2 - x[1]))
    if axis == 'v':
        a = [row[:p] for row in grid]
        b = [row[p+1:] for row in grid]
    else:
        a, b = grid[:p], grid[p+1:]
    nr, nc = min(len(a), len(b)), min(len(a[0]), len(b[0]))
    a = [row[:nc] for row in a[:nr]]
    b = [row[:nc] for row in b[:nr]]
    common = set(v for row in a for v in row) & set(v for row in b for v in row)
    # The panels share exactly one color: preserve it, marking its overlap.
    color = next(iter(common)) if len(common) == 1 else Counter(v for row in a for v in row if v in common).most_common(1)[0][0]
    return [[3 if a[r][c] == color and b[r][c] == color else color
             for c in range(nc)] for r in range(nr)]
